from taf.rfrl.l3_call.connection.exceptions import InvalidRan
from taf.rfrl.l3_call.connection.ssh_connection.classical_ssh_connection import ClassicalSshConnection
from taf.rfrl.l3_call.connection.ssh_connection.cloud_ssh_connection import CloudSshConnection


class SshConnectionFactory:
    """
    Creates ClassicalSshConnection or CloudSshConnection instances
    """

    @staticmethod
    def create_connection(ran, node):
        """
        Creates and returns an instance of the appropriate connection class
        based on the given RAN and node type.

        :param ran: RAN type: cloud/classical
        :type ran: str
        :param node: Node for which SSH connection is needed: enb/gnb
        :type node: str
        :return: The connection instance.
        :rtype: ClassicalSSHConnection or CloudSSHConnection
        """
        if ran == "cloud":
            return CloudSshConnection()
        elif ran == "classical":
            return ClassicalSshConnection(node=node)
        else:
            raise InvalidRan("RAN must be either cloud or classical!")
